using HomeLibrary;
using Microsoft.AspNetCore.DataProtection;
using System.Text.Json;
using System.Net;
using WebPush;
public static class CompanionFeaturesTests {
 static void Check(bool value,string name){if(!value)throw new Exception("Companion: "+name);Console.WriteLine("PASS "+name);}
 static void Bad(Action action){try{action();throw new Exception("Expected validation failure");}catch(LibraryError){}}
 static JsonElement Json(object input)=>JsonSerializer.SerializeToElement(input,Library.Json);
 sealed class FakePush:IPushTransport {public int Count;public Task Send(WebSubscription sub,VapidDetails keys,CancellationToken stop){Count++;Check(keys.Subject=="https://library.example"&&keys.PublicKey!=""&&keys.PrivateKey!="","VAPID identity available only to transport");return Task.CompletedTask;}}
 sealed class FakeHttp:HttpMessageHandler {public int Count;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken stop){Count++;var text=request.RequestUri!.AbsolutePath.Contains("/works/")?"{\"description\":{\"value\":\"<b>A lovely book</b> &amp; friends.\"}}":"{\"works\":[{\"key\":\"/works/OL123W\"}]}";return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(text)});}}
 public static async Task Run(string directory,IDataProtectionProvider protection){Directory.CreateDirectory(directory);using var store=new Store(directory,protection);using var accounts=new BorrowerAccounts(directory);var browsers=new BrowserAdmins(directory,"https://library.example",protection);
  void Change(string action,object input)=>store.Apply(new(action,Json(input),store.Read().Revision));
  Change("setLibraryTheme",new{libraryTheme="forest"});Check(store.Read().State.LibraryTheme=="forest","shared palette stored in authoritative library");Bad(()=>Change("setLibraryTheme",new{libraryTheme="<script>"}));Bad(()=>Change("setLibraryIcon",new{icon192="PHN2Zz4=",icon512="PHN2Zz4="}));Check(JsonSerializer.Deserialize<LibraryState>("{}",Library.Json)!.LibraryTheme=="","legacy palette remains migratable from existing browser");
  Change("addBook",new{isbn="9780140328721",title="Matilda",author="Roald Dahl",description="A librarian’s description."});Change("updateBook",new{copyId="BK-0001",isbn="9780140328721",title="Matilda",author="Roald Dahl"});Check(store.Read().State.Books[0].Description=="A librarian’s description.","older clients preserve stored descriptions when editing other fields");var handler=new FakeHttp();var about=new BookAbout(new HttpClient(handler),new CoverSettings(directory,protection,""));Check((await about.Find(store.Read().State.Books[0],default)).Source=="Library description"&&handler.Count==0,"manual about text requires no provider request");var result=await about.Find(new(){Isbn="9780141439518"},default);Check(result.Description=="A lovely book & friends."&&result.Source=="Open Library","short provider description safely reduced to plain text with source");await about.Find(new(){Isbn="9780141439518"},default);Check(handler.Count==2,"metadata cache prevents repeated provider lookups");
  var grant=Json(browsers.Pair());var enrolled=browsers.Enroll(grant.GetProperty("code").GetString()!,"Test iPhone");Check(browsers.Resolve(enrolled.Token)?.Id==enrolled.Device.Id,"private one-use browser pairing authorizes exact device");Bad(()=>browsers.Enroll(grant.GetProperty("code").GetString()!,"Replay"));Check(browsers.Resolve(enrolled.Token+"x")==null,"malformed browser cookie cannot authenticate");var restarted=new BrowserAdmins(directory,"https://library.example",protection);Check(restarted.Resolve(enrolled.Token)!=null&&!System.Text.Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(directory,"browser-admins.protected"))).Contains("Test iPhone"),"browser pairing survives restart in protected storage");
  var borrower=accounts.Register(new("notify.reader","Testing a long password!","Reader","reader@example.com",""));borrower=accounts.Approve(new(borrower.Id),store);Change("checkout",new{copyId="BK-0001",borrowerId=borrower.BorrowerId,checkoutDate=Library.Today,dueDate=Library.Today});
  var fake=new FakePush();var push=new PushNotifications(directory,"https://library.example",protection,fake,store,accounts,browsers);WebSubscription Sub(string id)=>new(){Endpoint="https://fcm.googleapis.com/fcm/send/"+id,Keys=new(){{"p256dh",Convert.ToBase64String(new byte[65])},{"auth",Convert.ToBase64String(new byte[16])}}};var bsub=Sub("borrower");var asub=Sub("admin");Bad(()=>PushNotifications.Validate(new(){Endpoint="http://localhost/admin"}));Bad(()=>PushNotifications.Validate(new(){Endpoint="https://evil.example/"}));
  push.Subscribe("borrower:"+borrower.Id,bsub);push.Subscribe("admin:"+enrolled.Device.Id,asub);await push.Run(DateTimeOffset.Now,default);Check(fake.Count==1,"opted-in borrower receives due-date reminder; no admin backlog notification");await push.Run(DateTimeOffset.Now,default);Check(fake.Count==1,"push reminder is deduplicated for loan/date/stage");
  Change("addBook",new{isbn="9780140328721",title="Matilda",author="Roald Dahl",confirmedDuplicates=new[]{"BK-0001"}});
  store.SubmitRequest(new("BK-0002","Visitor","visitor@example.com","Request",Guid.NewGuid().ToString(),"9780140328721","Matilda"));await push.Run(DateTimeOffset.Now,default);Check(fake.Count==2,"new borrowing request notifies opted-in admin only");await push.Run(DateTimeOffset.Now,default);Check(fake.Count==2,"new-request notification deduplicates between polls");
  accounts.Register(new("new.reader","Disposable new reader password!","Another reader","",""));await push.Run(DateTimeOffset.Now,default);Check(fake.Count==3,"new account approval notifies opted-in admin");
  Change("requestRenewal",new{loanId=store.Read().State.Loans.First(l=>l.ReturnedDate==null).Id});await push.Run(DateTimeOffset.Now,default);Check(fake.Count==4,"new renewal request notifies opted-in admin");await push.Run(DateTimeOffset.Now,default);Check(fake.Count==4,"account and renewal alerts deduplicate between polls");
  Change("returnBook",new{copyId="BK-0001"});await push.Run(DateTimeOffset.Now.AddDays(7),default);Check(fake.Count==4,"returned books cannot produce overdue notifications");accounts.Block(borrower.Id);browsers.Revoke(enrolled.Device.Id);await push.Run(DateTimeOffset.Now,default);Check(Json(push.Options("borrower:"+borrower.Id)).GetProperty("subscriptions").GetInt32()==0&&Json(push.Options("admin:"+enrolled.Device.Id)).GetProperty("subscriptions").GetInt32()==0,"blocked borrower and revoked admin subscriptions removed");Check(browsers.Resolve(enrolled.Token)==null,"revoking browser immediately rejects old cookie");var raw=System.Text.Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(directory,"web-push.protected")));Check(!raw.Contains("fcm.googleapis.com")&&!raw.Contains(borrower.Id),"push endpoints and owner identifiers encrypted at rest");
 }
}
